BEGIN;
DO $test$
DECLARE
 customer_id uuid:=gen_random_uuid();c1 uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();staff_id uuid:=gen_random_uuid();admin_id uuid:=gen_random_uuid();
 bid uuid;other_id uuid;request jsonb;stamp timestamptz;old_stamp timestamptz;receipt uuid:=gen_random_uuid();answer jsonb;again jsonb;err text;n integer;before_history integer;before_notifications integer;
BEGIN
 INSERT INTO auth.users(id,raw_user_meta_data) VALUES
 (customer_id,'{"full_name":"IRBI rollback change customer"}'),(c1,'{"full_name":"IRBI rollback cleaner one"}'),(c2,'{"full_name":"IRBI rollback cleaner two"}'),
 (staff_id,'{"full_name":"IRBI rollback change dispatcher"}'),(admin_id,'{"full_name":"IRBI rollback change admin"}');
 UPDATE public.profiles SET role='cleaner' WHERE id IN(c1,c2);
 UPDATE public.profiles SET role='dispatcher' WHERE id=staff_id;
 UPDATE public.profiles SET role='admin' WHERE id=admin_id;
 PERFORM set_config('request.jwt.claim.sub',customer_id::text,true);
 PERFORM set_config('request.jwt.claims',json_build_object('sub',customer_id,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 request:=jsonb_build_object('p_service','regular','p_rooms',1,'p_scheduled_at',now()+interval '50 days','p_address','Rollback-only booking changes','p_property_type','apartment','p_bathrooms',1,'p_area_m2',35,'p_phone','+380000000000','p_apartment','','p_entrance','','p_floor','','p_access_notes','','p_frequency','once','p_addons','{"oven":true}'::jsonb);
 bid:=public.irbi_customer_request_once(gen_random_uuid(),request);
 other_id:=public.irbi_customer_request_once(gen_random_uuid(),request||jsonb_build_object('p_scheduled_at',now()+interval '54 days'));
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=bid;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'cancel','Customer forbidden',stamp);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'staff_required' THEN RAISE EXCEPTION 'Customer can manage staff changes';END IF;
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 PERFORM public.irbi_staff_confirm_request(bid,now()+interval '50 days',120,1500,stamp);
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=other_id;
 PERFORM public.irbi_staff_confirm_request(other_id,now()+interval '54 days',120,1500,stamp);
 PERFORM public.irbi_staff_action(other_id,'assign',c2,null);
 PERFORM public.irbi_staff_action(bid,'assign',c1,null);
 err:=null;BEGIN PERFORM public.assign_booking_cleaner(bid,c2);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS NULL THEN RAISE EXCEPTION 'Legacy assignment bypasses managed reassignment';END IF;
 err:=null;BEGIN PERFORM public.advance_booking_status(bid,'cancelled');EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'use_managed_booking_change' THEN RAISE EXCEPTION 'Legacy cancellation bypasses guards';END IF;
 PERFORM set_config('request.jwt.claim.sub',c1::text,true);
 PERFORM public.irbi_staff_action(bid,'accept',null,null);
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=bid;old_stamp:=stamp;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'reschedule','Cleaner forbidden',stamp,now()+interval '52 days',120);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'staff_required' THEN RAISE EXCEPTION 'Cleaner can reschedule';END IF;
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 SELECT count(*) INTO before_history FROM public.booking_status_history WHERE booking_id=bid;
 -- Notifications are read as the customer before returning to staff.
 PERFORM set_config('request.jwt.claim.sub',customer_id::text,true);
 SELECT count(*) INTO before_notifications FROM public.irbi_notifications WHERE booking_id=bid;
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 answer:=public.irbi_change_booking(receipt,bid,'reschedule','Agreed new date',stamp,now()+interval '52 days',120);
 IF NOT EXISTS(SELECT 1 FROM public.bookings WHERE id=bid AND status='assigned' AND accepted_at IS NULL AND assigned_cleaner_id=c1 AND total=1500 AND cleaning_features->'requested_addons'->>'oven'='true') THEN RAISE EXCEPTION 'Reschedule lost booking state';END IF;
 again:=public.irbi_change_booking(receipt,bid,'reschedule','Agreed new date',old_stamp,now()+interval '52 days',120);
 IF again IS DISTINCT FROM answer THEN RAISE EXCEPTION 'Uncertain retry did not return same result';END IF;
 IF (SELECT count(*) FROM public.booking_change_events WHERE booking_id=bid)<>1 THEN RAISE EXCEPTION 'Duplicate change event';END IF;
 IF (SELECT count(*) FROM public.booking_status_history WHERE booking_id=bid)<>before_history+1 THEN RAISE EXCEPTION 'Duplicate status history';END IF;
 PERFORM set_config('request.jwt.claim.sub',customer_id::text,true);
 IF (SELECT count(*) FROM public.irbi_notifications WHERE booking_id=bid)<>before_notifications+1 THEN RAISE EXCEPTION 'Duplicate or missing customer notification';END IF;
 IF EXISTS(SELECT 1 FROM public.booking_change_events WHERE booking_id=bid) THEN RAISE EXCEPTION 'Customer can read internal change reasons';END IF;
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 err:=null;BEGIN PERFORM public.irbi_change_booking(receipt,bid,'reschedule','Changed reason',old_stamp,now()+interval '52 days',120);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'change_request_changed' THEN RAISE EXCEPTION 'Receipt allows different request';END IF;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'cancel','Old browser version',old_stamp);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'booking_changed' THEN RAISE EXCEPTION 'Stale browser version accepted';END IF;
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=bid;
 answer:=public.irbi_change_booking(gen_random_uuid(),bid,'reassign','New cleaner agreed',stamp,null,null,c2);
 IF NOT EXISTS(SELECT 1 FROM public.bookings WHERE id=bid AND assigned_cleaner_id=c2 AND status='assigned') THEN RAISE EXCEPTION 'Reassignment failed';END IF;
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=bid;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'reschedule','Conflicting time',stamp,now()+interval '54 days',120);EXCEPTION WHEN exclusion_violation THEN err:='conflict';END;
 IF err IS DISTINCT FROM 'conflict' THEN RAISE EXCEPTION 'Schedule conflict was accepted';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bookings WHERE id=bid AND scheduled_at=now()+interval '52 days' AND updated_at=stamp) THEN RAISE EXCEPTION 'Conflict partially updated booking';END IF;
 PERFORM set_config('request.jwt.claim.sub',c2::text,true);
 PERFORM public.irbi_set_shift(now()+interval '56 days',now()+interval '56 days 3 hours','unavailable','Rollback unavailable');
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'reschedule','Unavailable time',stamp,now()+interval '56 days',120);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'cleaner_unavailable' THEN RAISE EXCEPTION 'Unavailable shift accepted';END IF;
 PERFORM set_config('request.jwt.claim.sub',c1::text,true);
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'decline','Not my booking',stamp);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'not_assigned' THEN RAISE EXCEPTION 'Another cleaner can decline booking';END IF;
 PERFORM set_config('request.jwt.claim.sub',c2::text,true);
 answer:=public.irbi_change_booking(gen_random_uuid(),bid,'decline','Internal private reason',stamp);
 IF EXISTS(SELECT 1 FROM public.bookings WHERE id=bid) THEN RAISE EXCEPTION 'Former cleaner retains booking access';END IF;
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 IF NOT EXISTS(SELECT 1 FROM public.bookings WHERE id=bid AND status='confirmed' AND assigned_cleaner_id IS NULL) THEN RAISE EXCEPTION 'Decline did not release assignment';END IF;
 PERFORM set_config('request.jwt.claim.sub',customer_id::text,true);
 IF EXISTS(SELECT 1 FROM public.booking_status_history WHERE booking_id=bid AND note LIKE '%Internal private reason%') THEN RAISE EXCEPTION 'Private decline reason leaked';END IF;
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 PERFORM public.irbi_staff_action(bid,'assign',c1,null);
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM public.irbi_admin_payroll_action(bid,c1,'cleaning',600,'draft','Rollback draft');
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=bid;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'cancel','Cancelled after draft',stamp);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'payroll_reconciliation_required' THEN RAISE EXCEPTION 'Accrual was silently ignored';END IF;
 PERFORM public.irbi_admin_payroll_action(bid,c1,'cleaning',600,'void','Rollback void');
 SELECT count(*) INTO before_history FROM public.booking_status_history WHERE booking_id=bid;
 answer:=public.irbi_change_booking(gen_random_uuid(),bid,'cancel','Customer requested cancellation',stamp);
 IF NOT EXISTS(SELECT 1 FROM public.bookings WHERE id=bid AND status='cancelled' AND assigned_cleaner_id IS NULL AND total=1500 AND cancellation_reason='Customer requested cancellation') THEN RAISE EXCEPTION 'Cancellation lost or changed financial state';END IF;
 IF (SELECT count(*) FROM public.booking_status_history WHERE booking_id=bid)<>before_history+1 THEN RAISE EXCEPTION 'Cancellation history duplicated';END IF;
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=bid;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),bid,'reschedule','Cannot reopen order',stamp,now()+interval '60 days',120);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'change_locked' THEN RAISE EXCEPTION 'Cancelled order was reopened';END IF;
 PERFORM set_config('request.jwt.claim.sub',c2::text,true);
 PERFORM public.irbi_staff_action(other_id,'accept',null,null);
 PERFORM public.irbi_staff_action(other_id,'depart',null,null);
 PERFORM set_config('request.jwt.claim.sub',staff_id::text,true);
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=other_id;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),other_id,'cancel','Already departed',stamp);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'change_locked' THEN RAISE EXCEPTION 'Departed order was cancelled through pre-departure workflow';END IF;
 PERFORM set_config('request.jwt.claim.sub',customer_id::text,true);
 other_id:=public.irbi_customer_request_once(gen_random_uuid(),request||jsonb_build_object('p_scheduled_at',now()+interval '65 days'));
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 INSERT INTO public.booking_expenses(booking_id,category,amount,description,recorded_by) VALUES(other_id,'other',25,'Rollback test cost',admin_id);
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=other_id;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),other_id,'cancel','Costs already recorded',stamp);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'cost_reconciliation_required' THEN RAISE EXCEPTION 'Direct expenses ignored';END IF;
 PERFORM set_config('request.jwt.claim.sub',customer_id::text,true);
 other_id:=public.irbi_customer_request_once(gen_random_uuid(),request||jsonb_build_object('p_scheduled_at',now()+interval '66 days'));
 RESET ROLE;
 INSERT INTO public.payment_records(booking_id,amount,status,method,idempotency_key,paid_at,recorded_by,recording_note) VALUES(other_id,100,'paid','cash','rollback:'||gen_random_uuid(),now(),admin_id,'Rollback fixture only');
 SET LOCAL ROLE authenticated;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 SELECT updated_at INTO stamp FROM public.bookings WHERE id=other_id;
 err:=null;BEGIN PERFORM public.irbi_change_booking(gen_random_uuid(),other_id,'cancel','Payment already recorded',stamp);EXCEPTION WHEN OTHERS THEN err:=sqlerrm;END;
 IF err IS DISTINCT FROM 'payment_reconciliation_required' THEN RAISE EXCEPTION 'Payment was silently ignored';END IF;
 RESET ROLE;
END $test$;
SELECT 'PASS: reschedule, reassignment, decline, cancellation, idempotency, concurrency, privacy, conflicts and financial guards' AS result;
ROLLBACK;
